// RUN (from the repository root): node docs/chair/2026-11-20/content/page/build/OUTPUT/proseNumerics.regen.mjs "$PWD" [--write]
// The prose-numerics baseline regenerated by tests/lint/proseNumerics.test.js's OWN scanner (its scanLiveTree, the
// same walk: src/, .js/.jsx, the landing fixture skipped, sorted), as that file's ceiling notes record each shrink.
// Prints the rows that left and the rows that came (path|line|category|snippet); with --write, writes the baseline.
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = process.argv[2];
const { scanProseNumericsSource } = await import(`${ROOT}/tests/helpers/proseNumericsWalk.js`);
const BASELINE_PATH = join(ROOT, 'tests/lint/.prose-numerics-baseline.json');
const GENERATED_SOURCES = new Set(['src/components/home/landingFixture.js']);
const walk = (dir, out = []) => {
  for (const entry of readdirSync(dir)) {
    const abs = join(dir, entry);
    if (statSync(abs).isDirectory()) walk(abs, out);
    else if (/\.(?:js|jsx)$/.test(entry)) {
      const rel = relative(ROOT, abs).replace(/\\/g, '/');
      if (!GENERATED_SOURCES.has(rel)) out.push(abs);
    }
  }
  return out;
};
const hits = [];
for (const abs of walk(join(ROOT, 'src')).sort()) {
  const path = relative(ROOT, abs).replace(/\\/g, '/');
  const r = scanProseNumericsSource({ source: readFileSync(abs, 'utf8'), path });
  hits.push(...r.hits);
  if (r.parseError) console.log(`PARSE ERROR ${path}: ${r.parseError}`);
}
const key = (h) => `${h.path}|${h.line}|${h.category}|${h.snippet}`;
const before = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
const b = new Set(before.map(key)), a = new Set(hits.map(key));
for (const k of before.map(key)) if (!a.has(k)) console.log(`LEFT  ${k}`);
for (const k of hits.map(key)) if (!b.has(k)) console.log(`CAME  ${k}`);
console.log(`baseline ${before.length} -> live ${hits.length}`);
if (process.argv.includes('--write')) { writeFileSync(BASELINE_PATH, `${JSON.stringify(hits, null, 2)}\n`); console.log('written'); }
